def score(program: str) -> float:
    import ast
    try:
        t = ast.parse(program)
        w = list(ast.walk(t))
        n = len(w)
        if n < 2:
            return 0.5
        c = sum(1 for x in w if isinstance(x, (ast.If, ast.For, ast.While)))
        return min(c * 3.0 / n, 1.0)
    except:
        return 0.5

def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
        node_count = sum(1 for _ in ast.walk(tree))
        return min(1.0, node_count / 100.0)
    except:
        return 0.0

