def score(program: str) -> float:
    try:
        t = ast.parse(program.strip())
    except Exception:
        return 0.01
    v = sum(1 + zlib.crc32(type(n).__name__.encode()) % 89 / 89 for n in ast.walk(t))
    return v / (v + 60)

def score(program: str) -> float:
    try:
        n = len(program)
        words = program.split()
        u = len(set(words))
        lines = program.count("\n") + 1
        x = n / 600.0 + u / 60.0 + lines / 40.0
        return x / (1.0 + x)
    except Exception:
        return 0.5
